useGSAP(() => {
  const introTween = gsap.to(introImage, {
    yPercent: 150,
    ease: 'none',
    scrollTrigger: {
      trigger: introSection,
      scroller,
      start: 'top top',
      end: 'bottom top',
      scrub: true,
    },
  });

  const sectionTween = gsap.fromTo(
    sectionImage,
    { yPercent: -10 },
    {
      yPercent: 10,
      ease: 'none',
      scrollTrigger: {
        trigger: section,
        scroller,
        start: 'top bottom',
        end: 'bottom top',
        scrub: true,
      },
    },
  );

  return () => {
    introTween.kill();
    sectionTween.kill();
  };
}, { scope: containerRef });
